int spin_lock_try_acquire(spin_lock_t *lock)
{
    int try_times;
    for(try_times = 0; try_times < MAX_TRY_TIMES; try_times++){
        if(lock->status == UNLOCKED)
            break;
    }

    if(lock->status == UNLOCKED)
        return TRUE;
    else
        return FALSE;
}

