ptr_t kernel_memCurr = KERNEL_MEM_BEGIN;
ptr_t user_memCurr = USER_MEM_BEGIN;

user_page_t user_page[USER_PAGE_NUM];
shm_page_t shm_page[SHM_PAGE_NUM];
disk_page_t disk_page[DISK_PAGE_NUM];
pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];

static PTE *get_leaf_pte(uintptr_t va, uintptr_t pgdir_pa, int create)
{
    PTE *pgdir = (PTE *)pa2kva(pgdir_pa);
    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;

    if (!get_attribute(pgdir[vpn2], _PAGE_PRESENT)) {
        if (!create) {
            return NULL;
        }

        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(pgdir + vpn2, (uint64_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(pgdir + vpn2, _PAGE_PRESENT);
    }

    PTE *second_level_pgdir = (PTE *)pa2kva(get_pa(pgdir[vpn2]));
    if (!get_attribute(second_level_pgdir[vpn1], _PAGE_PRESENT)) {
        if (!create) {
            return NULL;
        }

        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(second_level_pgdir + vpn1,
                (uint64_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(second_level_pgdir + vpn1, _PAGE_PRESENT);
    }

    PTE *last_level_pgdir = (PTE *)pa2kva(get_pa(second_level_pgdir[vpn1]));
    return last_level_pgdir + vpn0;
}

static void map_leaf_page(PTE *pgtable, uintptr_t pa)
{
    *pgtable = 0;
    set_pfn(pgtable, pa >> NORMAL_PAGE_SHIFT);
    set_attribute(pgtable, _PAGE_PRESENT);
    set_attribute(pgtable, _PAGE_READ);
    set_attribute(pgtable, _PAGE_WRITE);
    set_attribute(pgtable, _PAGE_EXEC);
    set_attribute(pgtable, _PAGE_USER);
    set_attribute(pgtable, _PAGE_ACCESSED);
    set_attribute(pgtable, _PAGE_DIRTY);
}

static int find_shm_slot(uintptr_t pa)
{
    for (int i = 0; i < SHM_PAGE_NUM; i++) {
        if (shm_page[i].count > 0 && shm_page[i].pa == pa) {
            return i;
        }
    }
    return -1;
}

// returns pa
PTE* alloc_pgdir_page()
{
    int i;
    for(i = 0; i < PGDIR_PAGE_NUM; i++){
        if(pgdir_page[i].valid == 0){
            break;
        }
    }
    assert(i != PGDIR_PAGE_NUM);
    pgdir_page[i].valid = 1;
    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
    return ret;
}

void free_pgdir_page(uintptr_t addr)
{
    int i = (addr - FREE_PGDIR_ADDR) / PAGE_SIZE;
    pgdir_page[i].valid = 0;
}

int pa2num(uintptr_t pa)
{
    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
}
ptr_t num2pa(int num)
{
    return (USER_MEM_BEGIN + num * PAGE_SIZE);
}

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int page_num = -1;
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].valid == 0) {
            page_num = i;
            break;
        }
    }

    if (page_num == -1) {
        ptr_t victim = selete_page();
        write_to_sd(victim);
        page_num = pa2num(victim);
    }

    user_page[page_num].valid = 1;
    user_page[page_num].pin = pin;
    user_page[page_num].pgtable = pgtable;
    memset((void *)pa2kva(num2pa(page_num)), 0, PAGE_SIZE);
    return num2pa(page_num);
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
    user_page[pa2num(baseAddr)].pin = 0;
    user_page[pa2num(baseAddr)].pgtable = NULL;
}

// returns pa
void *kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(kernel_memCurr, 4);
    kernel_memCurr = ret + size;
    return (void*)ret;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    ptr_t ret = 0;
    int best_class = 4;

    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL) {
            continue;
        }

        PTE *pgtable = user_page[i].pgtable;
        if (!get_attribute(*pgtable, _PAGE_PRESENT)) {
            continue;
        }

        int accessed = get_attribute(*pgtable, _PAGE_ACCESSED);
        int dirty = get_attribute(*pgtable, _PAGE_DIRTY);
        int page_class = (accessed ? 2 : 0) + (dirty ? 1 : 0);

        if (page_class < best_class) {
            best_class = page_class;
            ret = num2pa(i);
            if (best_class == 0) {
                break;
            }
        }

        if (accessed) {
            clear_attribute(pgtable, _PAGE_ACCESSED);
        }
    }

    assert(ret != 0);
    return ret;
}

void write_to_sd(ptr_t pa)
{
    int slot = -1;
    for (int i = 0; i < DISK_PAGE_NUM; i++) {
        if (disk_page[i].valid == 0) {
            slot = i;
            break;
        }
    }

    assert(slot != -1);
    sbi_sd_write(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));

    PTE *pgtable = user_page[pa2num(pa)].pgtable;
    assert(pgtable != NULL);
    *pgtable = 0;
    set_pfn(pgtable, slot);
    set_attribute(pgtable, _PAGE_SOFT);
    disk_page[slot].valid = 1;
    free_user_page(pa);
    flush_tlb_all();
}

unsigned long free_page_num()
{
    unsigned long ret = 0;
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            ret++;
        }
    }
    return ret;
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    pgdir_kva[0x101] = kernel_pgdir[0x101];

    PTE *low_second_level = alloc_pgdir_page();
    set_pfn(pgdir_kva + 0, (uint64_t)low_second_level >> NORMAL_PAGE_SHIFT);
    set_attribute(pgdir_kva + 0, _PAGE_PRESENT);

    PTE *low_second_level_kva = (PTE *)pa2kva((uintptr_t)low_second_level);
    PTE *low_last_level = alloc_pgdir_page();
    set_pfn(low_second_level_kva + 0,
            (uint64_t)low_last_level >> NORMAL_PAGE_SHIFT);
    set_attribute(low_second_level_kva + 0, _PAGE_PRESENT);

    PTE *low_last_level_kva = (PTE *)pa2kva((uintptr_t)low_last_level);
    for (int i = 0x10; i <= 0x12; i++) {
        ptr_t pa = alloc_user_page(0, low_last_level_kva + i);
        map_leaf_page(low_last_level_kva + i, pa);
    }

    PTE *stack_second_level = alloc_pgdir_page();
    set_pfn(pgdir_kva + 0x3c,
            (uint64_t)stack_second_level >> NORMAL_PAGE_SHIFT);
    set_attribute(pgdir_kva + 0x3c, _PAGE_PRESENT);

    PTE *stack_second_level_kva = (PTE *)pa2kva((uintptr_t)stack_second_level);
    PTE *stack_last_level = alloc_pgdir_page();
    set_pfn(stack_second_level_kva + 0,
            (uint64_t)stack_last_level >> NORMAL_PAGE_SHIFT);
    set_attribute(stack_second_level_kva + 0, _PAGE_PRESENT);

    PTE *stack_last_level_kva = (PTE *)pa2kva((uintptr_t)stack_last_level);
    ptr_t stack_pa = alloc_user_page(0, stack_last_level_kva + 0xf);
    map_leaf_page(stack_last_level_kva + 0xf, stack_pa);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    if (pgdir == NULL || pgdir == (PTE *)PGDIR_PA) {
        return;
    }

    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    for (int vpn2 = 0; vpn2 < NUM_PTE_ENTRY; vpn2++) {
        if (vpn2 == 0x101 || !get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)) {
            continue;
        }

        PTE *second_level_pgdir =
            (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
        for (int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++) {
            if (!get_attribute(second_level_pgdir[vpn1], _PAGE_PRESENT)) {
                continue;
            }

            PTE *last_level_pgdir =
                (PTE *)pa2kva(get_pa(second_level_pgdir[vpn1]));
            for (int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++) {
                PTE entry = last_level_pgdir[vpn0];
                if (get_attribute(entry, _PAGE_PRESENT)) {
                    uintptr_t pa = get_pa(entry);
                    int shm_slot = find_shm_slot(pa);
                    if (shm_slot >= 0) {
                        shm_page[shm_slot].count--;
                        if (shm_page[shm_slot].count == 0) {
                            free_user_page(pa);
                            shm_page[shm_slot].pa = 0;
                        }
                    } else {
                        free_user_page(pa);
                    }
                } else if (get_attribute(entry, _PAGE_SOFT)) {
                    int slot = get_pfn(entry);
                    if (slot >= 0 && slot < DISK_PAGE_NUM) {
                        disk_page[slot].valid = 0;
                    }
                }
                last_level_pgdir[vpn0] = 0;
            }

            free_pgdir_page(kva2pa((uintptr_t)last_level_pgdir));
            second_level_pgdir[vpn1] = 0;
        }

        free_pgdir_page(kva2pa((uintptr_t)second_level_pgdir));
        pgdir_kva[vpn2] = 0;
    }

    free_pgdir_page((uintptr_t)pgdir);
}

