{
    read_superblock();
    if(mode == 1){
        superblock->magic = 0x0;
        write_superblock();
    }

    if(superblock->magic == MAGIC){
        return 0;
    }

    mkfs(1);
    enable_sum();
    *print_location_y = *print_location_y + 11;
    disable_sum();
    return 1;
}

