volatile superblock_t* superblock = SUPERBLOCK_CACHE;
volatile uintptr_t blockmap = BLOCKMAP_CACHE;
volatile uintptr_t inodemap = INODEMAP_CACHE;
volatile uintptr_t cached_inode_base = INODE_CACHE;
volatile uintptr_t cached_block_base = BLOCK_CACHE;
volatile uint16_t cached_inode_id;
volatile uint32_t cached_block_id;

uint16_t current_dir_inode;
uint32_t current_dir_block;

static int is_root_block_ref(uint16_t inode_id, const inode_t *inode,
                             uint32_t logical_idx, uint32_t block_id)
{
    return inode_id == superblock->root_inode_id && inode->mode == DIR &&
           logical_idx == 0 && inode->size != 0 && block_id == 0;
}

static int is_special_name(const char *name)
{
    return !strcmp(name, ".") || !strcmp(name, "..");
}

static int valid_leaf_name(const char *name)
{
    int length = strlen(name);
    return length > 0 && length < (int)sizeof(((dir_entry_t *)0)->name) &&
           !is_special_name(name);
}

static void init_entry(dir_entry_t *entry, uint8_t type, const char *name,
                       uint16_t inode_id)
{
    entry->type = type;
    memset(entry->name, 0, sizeof(entry->name));
    strcpy((char *)entry->name, name);
    entry->inode = inode_id;
}

void fs_read_inode_copy(uint16_t inode_id, inode_t *inode)
{
    *inode = *(inode_t *)read_inode(inode_id);
}

void fs_write_inode_copy(uint16_t inode_id, const inode_t *inode)
{
    inode_t *cached_inode = (inode_t *)read_inode(inode_id);
    *cached_inode = *inode;
    write_inode(inode_id);
}

static uint32_t inode_block_count(uint16_t inode_id, const inode_t *inode)
{
    uint32_t count = (inode->size + PAGE_SIZE - 1) / PAGE_SIZE;
    if (count == 0 && inode->mode == DIR) {
        count = 1;
    }

    for (uint32_t i = 0; i < 10; i++) {
        if (inode->direct_blocks[i] != 0 ||
            is_root_block_ref(inode_id, inode, i, inode->direct_blocks[i])) {
            if (count < i + 1) {
                count = i + 1;
            }
        }
    }

    for (uint32_t table = 0; table < 2; table++) {
        if (inode->indirect_blocks[table] == 0) {
            continue;
        }

        read_block(inode->indirect_blocks[table]);
        uint32_t *indirect = (uint32_t *)cached_block_base;
        for (uint32_t i = 0; i < PAGE_SIZE / sizeof(uint32_t); i++) {
            if (indirect[i] != 0) {
                uint32_t logical_idx = 10 + table * (PAGE_SIZE / sizeof(uint32_t)) + i;
                if (count < logical_idx + 1) {
                    count = logical_idx + 1;
                }
            }
        }
    }

    return count;
}

uint32_t fs_get_data_block(uint16_t inode_id, uint32_t logical_idx, int create)
{
    inode_t inode;
    fs_read_inode_copy(inode_id, &inode);

    if (logical_idx < 10) {
        uint32_t block_id = inode.direct_blocks[logical_idx];
        if (block_id == 0 &&
            !is_root_block_ref(inode_id, &inode, logical_idx, block_id)) {
            if (!create) {
                return 0;
            }

            block_id = alloc_block();
            if (block_id == 0xffffffff) {
                return 0xffffffff;
            }
            inode.direct_blocks[logical_idx] = block_id;
            fs_write_inode_copy(inode_id, &inode);
        }
        return block_id;
    }

    if (logical_idx >= 10 + 2 * (PAGE_SIZE / sizeof(uint32_t))) {
        return 0xffffffff;
    }

    uint32_t table_idx = logical_idx >= 10 + PAGE_SIZE / sizeof(uint32_t) ? 1 : 0;
    uint32_t table_block = inode.indirect_blocks[table_idx];
    if (table_block == 0) {
        if (!create) {
            return 0;
        }

        table_block = alloc_block();
        if (table_block == 0xffffffff) {
            return 0xffffffff;
        }
        inode.indirect_blocks[table_idx] = table_block;
        fs_write_inode_copy(inode_id, &inode);
    }

    uint32_t entry_idx = logical_idx - 10 - table_idx * (PAGE_SIZE / sizeof(uint32_t));
    read_block(table_block);
    uint32_t data_block = ((uint32_t *)cached_block_base)[entry_idx];
    if (data_block == 0 && create) {
        data_block = alloc_block();
        if (data_block == 0xffffffff) {
            return 0xffffffff;
        }
        read_block(table_block);
        ((uint32_t *)cached_block_base)[entry_idx] = data_block;
        write_block(table_block);
    }

    return data_block;
}

int fs_lookup_entry(uint16_t dir_inode_id, const char *name, dir_entry_t *entry,
                    uint32_t *block_id, uint32_t *slot_id)
{
    inode_t dir_inode;
    fs_read_inode_copy(dir_inode_id, &dir_inode);
    if (dir_inode.mode != DIR) {
        return 0;
    }

    uint32_t block_count = inode_block_count(dir_inode_id, &dir_inode);
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t cur_block = fs_get_data_block(dir_inode_id, logical_idx, 0);
        if (cur_block == 0xffffffff) {
            return 0;
        }
        if (cur_block == 0 &&
            !is_root_block_ref(dir_inode_id, &dir_inode, logical_idx, cur_block)) {
            continue;
        }

        read_block(cur_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            if (dir->entry[i].type != EMPTY &&
                !strcmp((char *)dir->entry[i].name, name)) {
                if (entry != NULL) {
                    *entry = dir->entry[i];
                }
                if (block_id != NULL) {
                    *block_id = cur_block;
                }
                if (slot_id != NULL) {
                    *slot_id = i;
                }
                return 1;
            }
        }
    }

    return 0;
}

int fs_alloc_entry_slot(uint16_t dir_inode_id, uint32_t *block_id,
                        uint32_t *slot_id)
{
    inode_t dir_inode;
    fs_read_inode_copy(dir_inode_id, &dir_inode);
    if (dir_inode.mode != DIR) {
        return 0;
    }

    uint32_t block_count = inode_block_count(dir_inode_id, &dir_inode);
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t cur_block = fs_get_data_block(dir_inode_id, logical_idx, 0);
        if (cur_block == 0xffffffff) {
            return 0;
        }
        if (cur_block == 0 &&
            !is_root_block_ref(dir_inode_id, &dir_inode, logical_idx, cur_block)) {
            continue;
        }

        read_block(cur_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            if (dir->entry[i].type == EMPTY) {
                *block_id = cur_block;
                *slot_id = i;
                return 1;
            }
        }
    }

    uint32_t new_block = fs_get_data_block(dir_inode_id, block_count, 1);
    if (new_block == 0xffffffff) {
        return 0;
    }

    *block_id = new_block;
    *slot_id = 0;
    return 1;
}

int fs_resolve_path(const char *path, int want_parent, uint16_t *inode_id,
                    uint8_t *type, uint32_t *block_id, char *leaf_name)
{
    if (path == NULL) {
        return 0;
    }

    read_superblock();

    uint16_t cur_inode_id = path[0] == '/' ? superblock->root_inode_id
                                           : current_dir_inode;
    inode_t cur_inode;
    fs_read_inode_copy(cur_inode_id, &cur_inode);
    uint8_t cur_type = cur_inode.mode;

    if (path[0] == '\0') {
        if (want_parent) {
            return 0;
        }
        if (inode_id != NULL) {
            *inode_id = cur_inode_id;
        }
        if (type != NULL) {
            *type = cur_type;
        }
        if (block_id != NULL) {
            *block_id = cur_inode.direct_blocks[0];
        }
        if (leaf_name != NULL) {
            leaf_name[0] = '\0';
        }
        return 1;
    }

    int pos = path[0] == '/' ? 1 : 0;
    while (path[pos] == '/') {
        pos++;
    }
    if (path[pos] == '\0') {
        if (want_parent) {
            return 0;
        }
        if (inode_id != NULL) {
            *inode_id = superblock->root_inode_id;
        }
        if (type != NULL) {
            *type = DIR;
        }
        if (block_id != NULL) {
            *block_id = superblock->root_block_id;
        }
        if (leaf_name != NULL) {
            leaf_name[0] = '\0';
        }
        return 1;
    }

    char component[29];
    while (1) {
        int len = 0;
        while (path[pos] != '\0' && path[pos] != '/') {
            if (len >= (int)sizeof(component) - 1) {
                return 0;
            }
            component[len++] = path[pos++];
        }
        component[len] = '\0';
        while (path[pos] == '/') {
            pos++;
        }
        int is_last = path[pos] == '\0';

        if (want_parent && is_last) {
            if (leaf_name != NULL) {
                strcpy(leaf_name, component);
            }
            if (inode_id != NULL) {
                *inode_id = cur_inode_id;
            }
            if (type != NULL) {
                *type = cur_type;
            }
            if (block_id != NULL) {
                *block_id = cur_inode.direct_blocks[0];
            }
            return 1;
        }

        if (!strcmp(component, ".")) {
            if (is_last) {
                break;
            }
            continue;
        }

        dir_entry_t entry;
        if (!fs_lookup_entry(cur_inode_id, component, &entry, NULL, NULL)) {
            return 0;
        }
        if (!is_last && entry.type != DIR) {
            return 0;
        }

        cur_inode_id = entry.inode;
        cur_type = entry.type;
        fs_read_inode_copy(cur_inode_id, &cur_inode);

        if (is_last) {
            if (inode_id != NULL) {
                *inode_id = cur_inode_id;
            }
            if (type != NULL) {
                *type = cur_type;
            }
            if (block_id != NULL) {
                *block_id = cur_inode.direct_blocks[0];
            }
            if (leaf_name != NULL) {
                leaf_name[0] = '\0';
            }
            return 1;
        }
    }

    if (want_parent) {
        return 0;
    }
    if (inode_id != NULL) {
        *inode_id = cur_inode_id;
    }
    if (type != NULL) {
        *type = cur_type;
    }
    if (block_id != NULL) {
        *block_id = cur_inode.direct_blocks[0];
    }
    if (leaf_name != NULL) {
        leaf_name[0] = '\0';
    }
    return 1;
}

int fs_add_entry(uint16_t dir_inode_id, const char *name, uint8_t type,
                 uint16_t inode_id)
{
    uint32_t entry_block;
    uint32_t entry_slot;
    if (!fs_alloc_entry_slot(dir_inode_id, &entry_block, &entry_slot)) {
        return 0;
    }

    read_block(entry_block);
    dir_t *dir = (dir_t *)cached_block_base;
    init_entry(&dir->entry[entry_slot], type, name, inode_id);
    write_block(entry_block);

    inode_t dir_inode;
    fs_read_inode_copy(dir_inode_id, &dir_inode);
    dir_inode.size += sizeof(dir_entry_t);
    fs_write_inode_copy(dir_inode_id, &dir_inode);
    return 1;
}

static void free_inode_data_blocks(uint16_t inode_id, const inode_t *inode)
{
    uint32_t block_count = inode_block_count(inode_id, inode);
    for (uint32_t i = 0; i < 10 && i < block_count; i++) {
        if (inode->direct_blocks[i] != 0 ||
            is_root_block_ref(inode_id, inode, i, inode->direct_blocks[i])) {
            free_block(inode->direct_blocks[i]);
        }
    }

    for (uint32_t table_idx = 0; table_idx < 2; table_idx++) {
        if (inode->indirect_blocks[table_idx] == 0) {
            continue;
        }

        read_block(inode->indirect_blocks[table_idx]);
        uint32_t *indirect = (uint32_t *)cached_block_base;
        for (uint32_t i = 0; i < PAGE_SIZE / sizeof(uint32_t); i++) {
            if (indirect[i] != 0) {
                free_block(indirect[i]);
            }
        }
        free_block(inode->indirect_blocks[table_idx]);
    }
}

int mkfs(int print)
{
    read_superblock();
    if (superblock->magic == MAGIC) {
        current_dir_inode = superblock->root_inode_id;
        current_dir_block = superblock->root_block_id;
        return 0;
    }

    memset((void *)blockmap, 0, 64 * 512);
    write_blockmap();
    memset((void *)inodemap, 0, 512);
    write_inodemap();

    memset((void *)superblock, 0, sizeof(superblock_t));
    superblock->magic = MAGIC;
    superblock->superblock_id = SUPERBLOCK_ID;
    superblock->superblock_num = 1;
    superblock->blockmap_id = BLOCKMAP_BEGIN_ID;
    superblock->blockmap_num = 64;
    superblock->inodemap_id = INODEMAP_ID;
    superblock->inodemap_num = 1;
    superblock->inode_id = INODE_BEGIN_ID;
    superblock->inode_num = 4096;
    superblock->block_id = BLOCK_BEGIN_ID;
    superblock->block_num = 262144;
    superblock->used_inode_num = 0;
    superblock->used_block_num = 0;
    write_superblock();

    uint16_t root_inode_id = alloc_inode();
    uint32_t root_block_id = alloc_block();
    superblock->root_inode_id = root_inode_id;
    superblock->root_block_id = root_block_id;
    write_superblock();

    inode_t root_inode;
    memset(&root_inode, 0, sizeof(root_inode));
    root_inode.mode = DIR;
    root_inode.owner = 0;
    root_inode.size = 2 * sizeof(dir_entry_t);
    root_inode.direct_blocks[0] = root_block_id;
    root_inode.link = 1;
    fs_write_inode_copy(root_inode_id, &root_inode);

    read_block(root_block_id);
    memset((void *)cached_block_base, 0, PAGE_SIZE);
    dir_t *root_dir = (dir_t *)cached_block_base;
    init_entry(&root_dir->entry[0], DIR, ".", root_inode_id);
    init_entry(&root_dir->entry[1], DIR, "..", root_inode_id);
    write_block(root_block_id);

    current_dir_inode = root_inode_id;
    current_dir_block = root_block_id;

    if (print) {
        prints("magic: %lx\n", superblock->magic);
        prints("root inode: %d\n", root_inode_id);
        prints("root block: %d\n", root_block_id);
    }

    return 1;
}

int do_mkfs(int mode, int* print_location_y)
{
    read_superblock();
    if(mode == 1){
        superblock->magic = 0x0;
        write_superblock();
    }

    if(superblock->magic == MAGIC){
        return 0;
    }

    mkfs(1);
    enable_sum();
    *print_location_y = *print_location_y + 11;
    disable_sum();
    return 1;
}

void do_statfs(int* print_location_y)
{
    read_superblock();
    prints("used inode: %d/%d\n", superblock->used_inode_num, superblock->inode_num);
    prints("used block: %d/%d\n", superblock->used_block_num, superblock->block_num);
    enable_sum();
    *print_location_y = *print_location_y + 2;
    disable_sum();
}

int do_mkdir(char* dirname)
{

    char leaf_name[29];
    uint16_t parent_inode_id;
    uint8_t parent_type;

    enable_sum();
    if (!fs_resolve_path(dirname, 1, &parent_inode_id, &parent_type, NULL, leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name)) {
        disable_sum();
        return 0;
    }

    if (fs_lookup_entry(parent_inode_id, leaf_name, NULL, NULL, NULL)) {
        disable_sum();
        return 0;
    }

    uint16_t new_inode_id = alloc_inode();
    uint32_t new_block_id = alloc_block();
    if (new_inode_id == 0xffff || new_block_id == 0xffffffff) {
        if (new_inode_id != 0xffff) {
            free_inode(new_inode_id);
        }
        if (new_block_id != 0xffffffff) {
            free_block(new_block_id);
        }
        disable_sum();
        return 0;
    }

    inode_t new_inode;
    memset(&new_inode, 0, sizeof(new_inode));
    new_inode.mode = DIR;
    new_inode.owner = current_running[cpu_id]->pid;
    new_inode.size = 2 * sizeof(dir_entry_t);
    new_inode.direct_blocks[0] = new_block_id;
    new_inode.link = 1;
    fs_write_inode_copy(new_inode_id, &new_inode);

    read_block(new_block_id);
    memset((void *)cached_block_base, 0, PAGE_SIZE);
    dir_t *new_dir = (dir_t *)cached_block_base;
    init_entry(&new_dir->entry[0], DIR, ".", new_inode_id);
    init_entry(&new_dir->entry[1], DIR, "..", parent_inode_id);
    write_block(new_block_id);

    int ret = fs_add_entry(parent_inode_id, leaf_name, DIR, new_inode_id);
    if (!ret) {
        free_block(new_block_id);
        free_inode(new_inode_id);
    }
    disable_sum();
    return ret;
}

int do_rmdir(char* dirname)
{
    char leaf_name[29];
    uint16_t parent_inode_id;
    uint8_t parent_type;

    enable_sum();
    if (!fs_resolve_path(dirname, 1, &parent_inode_id, &parent_type, NULL, leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name)) {
        disable_sum();
        return 0;
    }

    dir_entry_t target_entry;
    uint32_t entry_block;
    uint32_t entry_slot;
    if (!fs_lookup_entry(parent_inode_id, leaf_name, &target_entry,
                         &entry_block, &entry_slot) ||
        target_entry.type != DIR) {
        disable_sum();
        return 0;
    }

    if (target_entry.inode == superblock->root_inode_id) {
        disable_sum();
        return 0;
    }

    inode_t dir_inode;
    fs_read_inode_copy(target_entry.inode, &dir_inode);
    uint32_t block_count = inode_block_count(target_entry.inode, &dir_inode);
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t dir_block = fs_get_data_block(target_entry.inode, logical_idx, 0);
        if (dir_block == 0xffffffff ||
            (dir_block == 0 &&
             !is_root_block_ref(target_entry.inode, &dir_inode, logical_idx, dir_block))) {
            continue;
        }

        read_block(dir_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            if (dir->entry[i].type != EMPTY &&
                strcmp((char *)dir->entry[i].name, ".") &&
                strcmp((char *)dir->entry[i].name, "..")) {
                disable_sum();
                return 0;
            }
        }
    }

    read_block(entry_block);
    dir_t *parent_dir = (dir_t *)cached_block_base;
    memset(&parent_dir->entry[entry_slot], 0, sizeof(parent_dir->entry[entry_slot]));
    write_block(entry_block);

    inode_t parent_inode;
    fs_read_inode_copy(parent_inode_id, &parent_inode);
    if (parent_inode.size >= sizeof(dir_entry_t)) {
        parent_inode.size -= sizeof(dir_entry_t);
    }
    fs_write_inode_copy(parent_inode_id, &parent_inode);

    free_inode_data_blocks(target_entry.inode, &dir_inode);
    free_inode(target_entry.inode);
    if (current_dir_inode == target_entry.inode) {
        current_dir_inode = parent_inode_id;
        current_dir_block = parent_inode.direct_blocks[0];
    }
    disable_sum();
    return 1;
}

int do_ls(char* dirname, int mode, int* print_location_y)
{
    uint16_t dir_inode_id;
    uint8_t dir_type;
    inode_t dir_inode;

    enable_sum();
    if ((dirname[0] == '\0' &&
         !fs_resolve_path("", 0, &dir_inode_id, &dir_type, NULL, NULL)) ||
        (dirname[0] != '\0' &&
         !fs_resolve_path(dirname, 0, &dir_inode_id, &dir_type, NULL, NULL)) ||
        dir_type != DIR) {
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(dir_inode_id, &dir_inode);
    uint32_t block_count = inode_block_count(dir_inode_id, &dir_inode);
    int printed_lines = 0;
    for (uint32_t logical_idx = 0; logical_idx < block_count; logical_idx++) {
        uint32_t dir_block = fs_get_data_block(dir_inode_id, logical_idx, 0);
        if (dir_block == 0xffffffff ||
            (dir_block == 0 &&
             !is_root_block_ref(dir_inode_id, &dir_inode, logical_idx, dir_block))) {
            continue;
        }

        read_block(dir_block);
        dir_t *dir = (dir_t *)cached_block_base;
        for (uint32_t i = 0; i < sizeof(dir->entry) / sizeof(dir->entry[0]); i++) {
            dir_entry_t entry = dir->entry[i];
            if (entry.type == EMPTY) {
                continue;
            }
            if (mode == 0 &&
                (!strcmp((char *)entry.name, ".") ||
                 !strcmp((char *)entry.name, ".."))) {
                continue;
            }

            if (mode == 0) {
                prints("%s\n", entry.name);
            } else {
                inode_t entry_inode;
                fs_read_inode_copy(entry.inode, &entry_inode);
                prints("%s %d %d %s\n",
                       entry.type == DIR ? "dir" : "file",
                       entry_inode.owner, entry_inode.size, entry.name);
            }
            printed_lines++;
        }
    }

    if (printed_lines == 0) {
        prints("\n");
        printed_lines = 1;
    }

    *print_location_y += printed_lines;
    disable_sum();
    return 1;
}

int do_cd(char* dirname)
{
    uint16_t dir_inode_id;
    uint8_t dir_type;
    inode_t dir_inode;

    enable_sum();
    if (!fs_resolve_path(dirname, 0, &dir_inode_id, &dir_type, NULL, NULL) ||
        dir_type != DIR) {
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(dir_inode_id, &dir_inode);
    current_dir_inode = dir_inode_id;
    current_dir_block = dir_inode.direct_blocks[0];
    disable_sum();
    return 1;
}

int do_link(char* filename, char* newfile, int mode)
{
    uint16_t src_inode_id;
    uint8_t src_type;
    char leaf_name[29];
    uint16_t parent_inode_id;
    uint8_t parent_type;

    enable_sum();
    if (!fs_resolve_path(filename, 0, &src_inode_id, &src_type, NULL, NULL) ||
        src_type != FILE ||
        !fs_resolve_path(newfile, 1, &parent_inode_id, &parent_type, NULL,
                         leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name) ||
        fs_lookup_entry(parent_inode_id, leaf_name, NULL, NULL, NULL)) {
        disable_sum();
        return 0;
    }

    int ret = 0;
    if (mode == 0) {
        inode_t src_inode;
        fs_read_inode_copy(src_inode_id, &src_inode);
        src_inode.link++;
        fs_write_inode_copy(src_inode_id, &src_inode);
        ret = fs_add_entry(parent_inode_id, leaf_name, FILE, src_inode_id);
    } else {
        uint16_t new_inode_id = alloc_inode();
        if (new_inode_id != 0xffff) {
            inode_t src_inode;
            fs_read_inode_copy(src_inode_id, &src_inode);
            src_inode.owner = current_running[cpu_id]->pid;
            src_inode.link = 1;
            fs_write_inode_copy(new_inode_id, &src_inode);
            ret = fs_add_entry(parent_inode_id, leaf_name, FILE, new_inode_id);
            if (!ret) {
                free_inode(new_inode_id);
            }
        }
    }

    disable_sum();
    return ret;
}

