#define MAX_PREV    5       // 最大支持的回退数

int print_location_x;
int print_location_y;

void check_print_location(){
    if(print_location_y == SHELL_END){
        print_location_y--;
        sys_move_cursor(1, print_location_y);
        sys_screen_scroll(SHELL_BEGIN + 1, SHELL_END - 1);    
    }
}

