static void wake_waiters(list_head *wait_list)
{
    while (!list_empty(wait_list)) {
        do_unblock(wait_list->next);
    }
}

static void release_binsems(pcb_t *task)
{
    for (int i = 0; i < task->binsem_num; i++) {
        int binsem_id = task->binsem_id[i];
        binsem_node_t *node = &binsem_nodes[binsem_id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *unblocked_list = node->block_queue.next;
            pcb_t *unblocked_pcb = list_entry(unblocked_list, pcb_t, list);
            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
            unblocked_pcb->binsem_num++;
            do_unblock(unblocked_list);
        }
    }
}

static void free_task_vm(pcb_t *task)
{
    if (task->pgdir != NULL && task->pgdir != (PTE *)PGDIR_PA) {
        free_process_user_page(task->pgdir);
        task->pgdir = (PTE *)PGDIR_PA;
    }
}

static void enter_zombie(pcb_t *task, int remove_from_list)
{
    wake_waiters(&task->wait_list);
    release_binsems(task);
    free_task_vm(task);

    if (remove_from_list) {
        list_del(&task->list);
    }

    task->status = TASK_ZOMBIE;
    if (task->mode == AUTO_CLEANUP_ON_EXIT) {
        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
    }
}

/* 
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE 
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    current_running[cpu_id]->cursor_x = screen_cursor_x[cpu_id];
    current_running[cpu_id]->cursor_y = screen_cursor_y[cpu_id];

    if (current_running[cpu_id]->status == TASK_RUNNING) {
        list_add_tail(&current_running[cpu_id]->list, &ready_queue);
        current_running[cpu_id]->status = TASK_READY;
        current_running[cpu_id]->ready_tick = get_ticks();
    } else if (current_running[cpu_id]->status == TASK_KILLED) {
        set_satp(SATP_MODE_SV39, 0, PGDIR_PA >> NORMAL_PAGE_SHIFT);
        local_flush_tlb_all();
        enter_zombie(current_running[cpu_id], 0);
    }

    current_running[cpu_id] = list_entry(max_priority_node(), pcb_t, list);
    list_del(&current_running[cpu_id]->list);
    current_running[cpu_id]->status = TASK_RUNNING;
    current_running[cpu_id]->cpu_id = cpu_id;
    current_cpu_running = current_running[cpu_id];

    set_satp(SATP_MODE_SV39, 0,
             (uintptr_t)current_running[cpu_id]->pgdir >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();

    vt100_move_cursor(current_running[cpu_id]->cursor_x,
                      current_running[cpu_id]->cursor_y);
    screen_cursor_x[cpu_id] = current_running[cpu_id]->cursor_x;
    screen_cursor_y[cpu_id] = current_running[cpu_id]->cursor_y;
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    pcb_t *new_pcb = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            new_pcb = &pcb[i];
            break;
        }
    }
    if (new_pcb == NULL) {
        return 0;
    }

    char kernel_file_name[64];
    int file_name_len = 0;
    enable_sum();
    while (file_name_len < (int)sizeof(kernel_file_name) - 1 &&
           file_name[file_name_len] != '\0') {
        kernel_file_name[file_name_len] = file_name[file_name_len];
        file_name_len++;
    }
    kernel_file_name[file_name_len] = '\0';

    unsigned char *binary = NULL;
    int length = 0;
    if (!get_elf_file(kernel_file_name, &binary, &length)) {
        disable_sum();
        return -1;
    }

    ptr_t kernel_stack_pa = alloc_user_page(1, NULL);
    new_pcb->kernel_sp = pa2kva(kernel_stack_pa + PAGE_SIZE);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_stack_base = USER_STACK_ADDR;
    new_pcb->pgdir = init_page_table();
    if (new_pcb->pgdir == NULL) {
        free_user_page(kernel_stack_pa);
        disable_sum();
        return -2;
    }

    uintptr_t entry =
        load_elf(binary, length, (uintptr_t)new_pcb->pgdir, alloc_page_helper);
    if (entry == 0) {
        free_process_user_page(new_pcb->pgdir);
        new_pcb->pgdir = (PTE *)PGDIR_PA;
        free_user_page(kernel_stack_pa);
        disable_sum();
        return -2;
    }

    uintptr_t stack_bottom = USER_STACK_ADDR - PAGE_SIZE;
    uintptr_t stack_kva =
        alloc_page_helper(stack_bottom, (uintptr_t)new_pcb->pgdir);
    uintptr_t user_sp = USER_STACK_ADDR;
    uintptr_t user_argv[argc > 0 ? argc + 1 : 1];

    for (int i = argc - 1; i >= 0; i--) {
        int arg_len = strlen(argv[i]) + 1;
        user_sp -= arg_len;
        if (user_sp < stack_bottom) {
            free_process_user_page(new_pcb->pgdir);
            new_pcb->pgdir = (PTE *)PGDIR_PA;
            free_user_page(kernel_stack_pa);
            disable_sum();
            return -2;
        }

        memcpy((uint8_t *)(stack_kva + user_sp - stack_bottom),
               (uint8_t *)argv[i], arg_len);
        user_argv[i] = user_sp;
    }
    user_argv[argc] = 0;

    user_sp = ROUNDDOWN(user_sp, sizeof(uintptr_t));
    user_sp -= (argc + 1) * sizeof(uintptr_t);
    if (user_sp < stack_bottom) {
        free_process_user_page(new_pcb->pgdir);
        new_pcb->pgdir = (PTE *)PGDIR_PA;
        free_user_page(kernel_stack_pa);
        disable_sum();
        return -2;
    }

    memcpy((uint8_t *)(stack_kva + user_sp - stack_bottom),
           (uint8_t *)user_argv, (argc + 1) * sizeof(uintptr_t));

    new_pcb->user_sp = user_sp;
    new_pcb->preempt_count = 0;
    init_list_head(&new_pcb->wait_list);
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = USER_PROCESS;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = 0;
    new_pcb->ready_tick = get_ticks();
    new_pcb->mask = current_running[cpu_id]->mask;

    regs_context_t *pt_regs =
        (regs_context_t *)(new_pcb->kernel_sp - sizeof(regs_context_t));
    new_pcb->kernel_sp -= sizeof(regs_context_t);

    pt_regs->regs[1] = (reg_t)entry;
    pt_regs->regs[2] = (reg_t)user_sp;
    pt_regs->regs[3] = (reg_t)__global_pointer$;
    pt_regs->regs[10] = (reg_t)argc;
    pt_regs->regs[11] = (reg_t)user_sp;
    pt_regs->sstatus = (reg_t)SR_SPIE;
    pt_regs->sepc = (reg_t)entry;
    pt_regs->sscratch = (reg_t)new_pcb;

    list_add_tail(&new_pcb->list, &ready_queue);
    local_flush_icache_all();
    disable_sum();
    return new_pcb->pid;
}

void do_exit()
{
    set_satp(SATP_MODE_SV39, 0, PGDIR_PA >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();
    enter_zombie(current_running[cpu_id], 1);
    scheduler();
}

// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running[cpu_id]->list, &sleep_queue);
    list_node_t* parameter = &current_running[cpu_id]->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

