#include <os/fs.h>
#include <os/disk.h>
#include <os/file.h>
#include <os/mm.h>
#include <os/sched.h>
#include <os/irq.h>
#include <os/string.h>
#include <assert.h>

#define FD_NUM 10
#define FS_PATH_MAX 256
#define FS_NAME_MAX 28
#define FS_MAX_FILE_BLOCKS (10 + 2 * (PAGE_SIZE / sizeof(uint32_t)))
#define FS_MAX_FILE_SIZE ((uint64_t)FS_MAX_FILE_BLOCKS * PAGE_SIZE)

fd_t fd_list[FD_NUM];

static int copy_user_string(char *dst, const char *src, int max_len)
{
    int i = 0;

    if (dst == NULL || src == NULL || max_len <= 0) {
        return 0;
    }

    while (i < max_len - 1) {
        dst[i] = src[i];
        if (dst[i] == '\0') {
            return 1;
        }
        i++;
    }

    dst[max_len - 1] = '\0';
    return 0;
}

static int valid_leaf_name(const char *name)
{
    return name != NULL && name[0] != '\0' &&
           strlen(name) < (int)sizeof(((dir_entry_t *)0)->name) &&
           strcmp(name, ".") && strcmp(name, "..");
}

static int valid_access_mode(int access)
{
    return access == O_RDONLY || access == O_WRONLY || access == O_RDWR;
}

static int create_file_kernel(const char *path, uint16_t *inode_id)
{
    uint16_t parent_inode_id;
    uint8_t parent_type;
    char leaf_name[FS_NAME_MAX + 1];

    if (!fs_resolve_path(path, 1, &parent_inode_id, &parent_type, NULL,
                         leaf_name) ||
        parent_type != DIR || !valid_leaf_name(leaf_name) ||
        fs_lookup_entry(parent_inode_id, leaf_name, NULL, NULL, NULL)) {
        return 0;
    }

    uint16_t new_inode_id = alloc_inode();
    if (new_inode_id == 0xffff) {
        return 0;
    }

    inode_t inode;
    memset(&inode, 0, sizeof(inode));
    inode.mode = FILE;
    inode.owner = current_running[cpu_id]->pid;
    inode.link = 1;
    fs_write_inode_copy(new_inode_id, &inode);

    if (!fs_add_entry(parent_inode_id, leaf_name, FILE, new_inode_id)) {
        free_inode(new_inode_id);
        return 0;
    }

    if (inode_id != NULL) {
        *inode_id = new_inode_id;
    }
    return 1;
}

int do_touch(char* filename)
{
    char path[FS_PATH_MAX];

    enable_sum();
    int copied = copy_user_string(path, filename, sizeof(path));
    disable_sum();
    if (!copied) {
        return 0;
    }

    return create_file_kernel(path, NULL);
}

int do_cat(char* filename, char* buffer)
{
    char path[FS_PATH_MAX];
    uint16_t inode_id;
    uint8_t type;
    inode_t inode;

    if (buffer == NULL) {
        return 0;
    }

    enable_sum();
    int copied = copy_user_string(path, filename, sizeof(path));
    disable_sum();
    if (!copied) {
        enable_sum();
        buffer[0] = '\0';
        disable_sum();
        return 0;
    }

    if (!fs_resolve_path(path, 0, &inode_id, &type, NULL, NULL) ||
        type != FILE) {
        enable_sum();
        buffer[0] = '\0';
        disable_sum();
        return 0;
    }

    fs_read_inode_copy(inode_id, &inode);
    if (inode.size == 0) {
        enable_sum();
        buffer[0] = '\0';
        disable_sum();
        return 1;
    }

    uint32_t block_id = fs_get_data_block(inode_id, 0, 0);
    if (block_id == 0 || block_id == 0xffffffff) {
        enable_sum();
        buffer[0] = '\0';
        disable_sum();
        return 0;
    }

    uint32_t copy_size = inode.size;
    if (copy_size >= PAGE_SIZE) {
        copy_size = PAGE_SIZE - 1;
    }

    read_block(block_id);
    enable_sum();
    memcpy((uint8_t *)buffer, (uint8_t *)cached_block_base, copy_size);
    buffer[copy_size] = '\0';
    disable_sum();
    return 1;
}

int do_fopen(char* filename, int access)
{
    char path[FS_PATH_MAX];
    uint16_t inode_id;
    uint8_t type;

    if (!valid_access_mode(access)) {
        return -1;
    }

    enable_sum();
    int copied = copy_user_string(path, filename, sizeof(path));
    disable_sum();
    if (!copied) {
        return -1;
    }

    if (!fs_resolve_path(path, 0, &inode_id, &type, NULL, NULL)) {
        if (access == O_RDONLY || !create_file_kernel(path, &inode_id)) {
            return -1;
        }
        type = FILE;
    }
    if (type != FILE) {
        return -1;
    }

    for (int i = 0; i < FD_NUM; i++) {
        if (fd_list[i].access == O_EMPTY) {
            fd_list[i].inode = inode_id;
            fd_list[i].access = access;
            fd_list[i].rd_pos = 0;
            fd_list[i].wr_pos = 0;
            return i;
        }
    }

    return -1;
}

int do_fread(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= FD_NUM || buffer == NULL || size <= 0 ||
        fd_list[fd].access == O_EMPTY ||
        (fd_list[fd].access != O_RDONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    inode_t inode;
    fs_read_inode_copy(fd_list[fd].inode, &inode);
    if (inode.mode != FILE || fd_list[fd].rd_pos >= inode.size) {
        return 0;
    }

    uint64_t readable = inode.size - fd_list[fd].rd_pos;
    if ((uint64_t)size < readable) {
        readable = size;
    }

    uint64_t start_pos = fd_list[fd].rd_pos;
    int copied = 0;
    enable_sum();
    while ((uint64_t)copied < readable) {
        uint64_t cur_pos = start_pos + copied;
        uint32_t block_idx = cur_pos / PAGE_SIZE;
        uint32_t block_offset = cur_pos % PAGE_SIZE;
        uint32_t block_id = fs_get_data_block(fd_list[fd].inode, block_idx, 0);
        uint32_t chunk = PAGE_SIZE - block_offset;
        if ((uint64_t)chunk > readable - copied) {
            chunk = readable - copied;
        }

        if (block_id == 0xffffffff) {
            break;
        }
        if (block_id == 0) {
            memset((uint8_t *)buffer + copied, 0, chunk);
        } else {
            read_block(block_id);
            memcpy((uint8_t *)buffer + copied,
                   (uint8_t *)cached_block_base + block_offset, chunk);
        }
        copied += chunk;
    }
    disable_sum();

    fd_list[fd].rd_pos = start_pos + copied;
    return copied;
}

int do_fwrite(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= FD_NUM || buffer == NULL || size <= 0 ||
        fd_list[fd].access == O_EMPTY ||
        (fd_list[fd].access != O_WRONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    inode_t inode;
    fs_read_inode_copy(fd_list[fd].inode, &inode);
    if (inode.mode != FILE || fd_list[fd].wr_pos >= FS_MAX_FILE_SIZE) {
        return 0;
    }

    uint64_t writable = size;
    if (writable > FS_MAX_FILE_SIZE - fd_list[fd].wr_pos) {
        writable = FS_MAX_FILE_SIZE - fd_list[fd].wr_pos;
    }

    uint64_t start_pos = fd_list[fd].wr_pos;
    int written = 0;
    enable_sum();
    while ((uint64_t)written < writable) {
        uint64_t cur_pos = start_pos + written;
        uint32_t block_idx = cur_pos / PAGE_SIZE;
        uint32_t block_offset = cur_pos % PAGE_SIZE;
        uint32_t block_id = fs_get_data_block(fd_list[fd].inode, block_idx, 1);
        uint32_t chunk = PAGE_SIZE - block_offset;
        if ((uint64_t)chunk > writable - written) {
            chunk = writable - written;
        }

        if (block_id == 0xffffffff || block_id == 0) {
            break;
        }

        read_block(block_id);
        memcpy((uint8_t *)cached_block_base + block_offset,
               (uint8_t *)buffer + written, chunk);
        write_block(block_id);
        written += chunk;
    }
    disable_sum();

    if (written > 0) {
        uint64_t new_size = start_pos + written;
        fd_list[fd].wr_pos = new_size;
        fs_read_inode_copy(fd_list[fd].inode, &inode);
        if (new_size > inode.size) {
            inode.size = new_size;
            fs_write_inode_copy(fd_list[fd].inode, &inode);
        }
    }

    return written;
}

void do_fclose(int fd)
{
    if (fd < 0 || fd >= FD_NUM) {
        return;
    }

    fd_list[fd].inode = 0;
    fd_list[fd].access = O_EMPTY;
    fd_list[fd].rd_pos = 0;
    fd_list[fd].wr_pos = 0;
}

