+    uint32_t entry_idx = logical_idx - 10 - table_idx * (PAGE_SIZE / sizeof(uint32_t));
+    read_block(table_block);
+    uint32_t data_block = ((uint32_t *)cached_block_base)[entry_idx];
+    if (data_block == 0 && create) {
+        data_block = alloc_block();
